<script>  
    window.onload = function() {
        viewPrescriptions();
    }
    function viewPrescriptions() {


        // dont pass flag in query parameter because it will fetched
        fetch('/graphql', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                query: `
